INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','inversion','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"inversion","title":"Inversion after negatives and in conditionals","level":"C1","order":62,"summary":"Recognise formal emphasis that places an auxiliary before the subject, and conditional forms that omit if.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Negative or limiting openings","Move only the first auxiliary","Conditional inversion without if","Scope of only and not until"],"rules":[{"title":"Negative or limiting openings","explanation":"After fronted negative or limiting expressions such as never, rarely and only then, formal English often uses **auxiliary–subject inversion** in the main clause. Add do-support if the original lexical verb has no auxiliary.","pattern":"**Rarely does she complain**.","commonMistakes":["Rarely she complains does not follow the standard emphatic inversion pattern after fronted rarely."],"examples":["Use formal inversion: “Rarely **does she prepare** the visitor guide without help.”","Use formal inversion: “Rarely **does she restore** the old portrait without help.”"],"skill":"form"},{"title":"Move only the first auxiliary","explanation":"If a verb phrase already has auxiliaries, move just the first one before the subject. Keep later auxiliaries and the main verb after the subject. The form resembles a question, but the sentence is still a statement.","pattern":"**Never have I been** so surprised.","commonMistakes":["Never have been I ... moves too much of the verb phrase before the subject."],"examples":["Use formal inversion: “Never **have they prepared** the visitor guide so quickly.”","Use formal inversion: “Never **have they restored** the old portrait so quickly.”"],"skill":"meaning"},{"title":"Conditional inversion without if","explanation":"Formal conditionals can omit if and begin with **had**, **were** or **should**. Had I known means if I had known. Were she to leave presents a hypothetical condition; should you need help presents a possible contingency.","pattern":"**Had I known**, I would have called.","commonMistakes":["Do not keep if as well as using this inverted conditional pattern."],"examples":["Replace “If we had prepared the visitor guide”: “**Had we prepared** the visitor guide, we would have finished earlier.”","Replace “If we had restored the old portrait”: “**Had we restored** the old portrait, we would have finished earlier.”"],"skill":"contrast"},{"title":"Scope of only and not until","explanation":"An opening such as Only after the meeting or Not until she arrived triggers inversion in the **main clause**, not in the subordinate time clause. Only modifying the subject does not normally trigger this inversion.","pattern":"Only after she arrived **did we begin**.","commonMistakes":["Only the manager knew has no inversion because only modifies the subject itself."],"examples":["Use inversion in the main clause: “Only after the call **did she prepare** the visitor guide.”","Use inversion in the main clause: “Only after the call **did she restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion","bc-inverted-conditions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Recognise formal emphasis that places an auxiliary before the subject, and conditional forms that omit if.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Negative or limiting openings","explanation":"After fronted negative or limiting expressions such as never, rarely and only then, formal English often uses **auxiliary–subject inversion** in the main clause. Add do-support if the original lexical verb has no auxiliary.","pattern":"**Rarely does she complain**.","commonMistakes":["Rarely she complains does not follow the standard emphatic inversion pattern after fronted rarely."],"examples":["Use formal inversion: “Rarely **does she prepare** the visitor guide without help.”","Use formal inversion: “Rarely **does she restore** the old portrait without help.”"],"skill":"form","id":"inversion-foundation-1","domain":"information","referenceIds":["bc-inversion","bc-inverted-conditions"],"readingVersion":"core-2026-09-v3"},{"title":"Move only the first auxiliary","explanation":"If a verb phrase already has auxiliaries, move just the first one before the subject. Keep later auxiliaries and the main verb after the subject. The form resembles a question, but the sentence is still a statement.","pattern":"**Never have I been** so surprised.","commonMistakes":["Never have been I ... moves too much of the verb phrase before the subject."],"examples":["Use formal inversion: “Never **have they prepared** the visitor guide so quickly.”","Use formal inversion: “Never **have they restored** the old portrait so quickly.”"],"skill":"meaning","id":"inversion-foundation-2","domain":"information","referenceIds":["bc-inversion","bc-inverted-conditions"],"readingVersion":"core-2026-09-v3"},{"title":"Conditional inversion without if","explanation":"Formal conditionals can omit if and begin with **had**, **were** or **should**. Had I known means if I had known. Were she to leave presents a hypothetical condition; should you need help presents a possible contingency.","pattern":"**Had I known**, I would have called.","commonMistakes":["Do not keep if as well as using this inverted conditional pattern."],"examples":["Replace “If we had prepared the visitor guide”: “**Had we prepared** the visitor guide, we would have finished earlier.”","Replace “If we had restored the old portrait”: “**Had we restored** the old portrait, we would have finished earlier.”"],"skill":"contrast","id":"inversion-foundation-3","domain":"information","referenceIds":["bc-inversion","bc-inverted-conditions"],"readingVersion":"core-2026-09-v3"},{"title":"Scope of only and not until","explanation":"An opening such as Only after the meeting or Not until she arrived triggers inversion in the **main clause**, not in the subordinate time clause. Only modifying the subject does not normally trigger this inversion.","pattern":"Only after she arrived **did we begin**.","commonMistakes":["Only the manager knew has no inversion because only modifies the subject itself."],"examples":["Use inversion in the main clause: “Only after the call **did she prepare** the visitor guide.”","Use inversion in the main clause: “Only after the call **did she restore** the old portrait.”"],"skill":"application","id":"inversion-foundation-4","domain":"information","referenceIds":["bc-inversion","bc-inverted-conditions"],"readingVersion":"core-2026-09-v3"},{"domain":"information","id":"locative-and-conditional-inversion","title":"Locative inversion and conditional alternatives","explanation":"Some locative openings allow the main verb before a noun subject: on the hill stood a castle. This differs from auxiliary inversion after a negative expression. Formal conditional inversion can begin with had, were or should, each preserving a particular conditional meaning. Pronoun subjects behave differently in many locative patterns.","pattern":"On the wall **hung a portrait**.","examples":["**Should you need help**, call us.","**Were she to resign**, we would need a replacement."],"commonMistakes":["With a personal pronoun, Here she comes is usual rather than Here comes she. Learn locative and negative inversion as separate constructions."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**Rarely does she complain**.","**Never have I been** so surprised.","**Had I known**, I would have called.","Only after she arrived **did we begin**."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["participle-clauses"],"readingReferenceIds":["bc-inversion","bc-inverted-conditions","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='inversion'
